define("local_hello/messages",["core/ajax","core/notification"],function(Ajax,Notification){var BUTTON_ID="local-hello-load-messages",LIST_ID="local-hello-ajax-list",renderMessages=function(container,messages){if(!Array.isArray(messages)||0===messages.length){container.textContent=container.dataset.emptyText||"";return}var list=document.createElement("ul");messages.forEach(function(item){var row=document.createElement("li");row.textContent=item.timecreated+" - "+item.message,list.appendChild(row)}),container.innerHTML="",container.appendChild(list)},loadMessages=function(button,container){var loadingText=button.dataset.loadingText||button.textContent,defaultText=button.dataset.defaultText||button.textContent;button.disabled=!0,button.textContent=loadingText,Ajax.call([{methodname:"local_hello_get_messages",args:{userid:0}}])[0].then(function(messages){return renderMessages(container,messages),button.disabled=!1,button.textContent=defaultText,null}).catch(function(error){button.disabled=!1,button.textContent=defaultText,Notification.exception(error)})},init=function(){var button=document.getElementById(BUTTON_ID),container=document.getElementById(LIST_ID);button&&container&&button.addEventListener("click",function(event){event.preventDefault(),loadMessages(button,container)})};return{init:init}});
